// Easing function for smooth scroll
function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : (t - 1) * (2 * t - 2) * (2 * t - 2) + 1;
}

// Function to show/hide the Back to Top button
function toggleBackToTopButton() {
  const backToTopBtn = document.getElementById('backToTopBtn');
  if (window.pageYOffset > 300) {
    backToTopBtn.style.display = 'block';
  } else {
    backToTopBtn.style.display = 'none';
  }
}

// Function to smoothly scroll to the top of the page
function scrollToTop() {
  const startY = window.pageYOffset;
  const distance = startY;
  const duration = 1000; // Time in milliseconds for the scroll animation
  let startTime = null;

  function animation(currentTime) {
    if (!startTime) startTime = currentTime;
    const timeElapsed = currentTime - startTime;
    const scrollY = startY - easeInOutCubic(timeElapsed / duration) * distance;
    window.scrollTo(0, scrollY);

    // Update scroll percentage attribute and display
    const backToTopBtn = document.getElementById('backToTopBtn');
    const currentScrollPercentage = Math.round((scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100);
    backToTopBtn.setAttribute('data-scroll-percentage', currentScrollPercentage);
    backToTopBtn.style.setProperty('--scroll-percentage', currentScrollPercentage + '%');

    if (timeElapsed < duration) requestAnimationFrame(animation);
  }

  requestAnimationFrame(animation);
}

// Function to update scroll percentage on scroll
function updateScrollPercentage() {
  const backToTopBtn = document.getElementById('backToTopBtn');
  const currentScrollPercentage = Math.round((window.pageYOffset / (document.documentElement.scrollHeight - window.innerHeight)) * 100);
  backToTopBtn.setAttribute('data-scroll-percentage', currentScrollPercentage);
  backToTopBtn.style.setProperty('--scroll-percentage', currentScrollPercentage + '%');
}

// Add event listeners
window.addEventListener('scroll', () => {
  toggleBackToTopButton();
  updateScrollPercentage();
});

document.getElementById('backToTopBtn').addEventListener('click', scrollToTop);
